function titleFromUrl(raw) {
  try {
    const u = new URL(raw);
    let host = u.hostname.replace(/^www\./, '');
    let path = u.pathname.replace(/\/$/, '');
    if (path && path !== '') {
      const last = path.split('/').filter(Boolean).pop() || '';
      const words = last.replace(/[-_]+/g, ' ').replace(/\.[a-z0-9]+$/i, '').trim();
      if (words) return words.charAt(0).toUpperCase() + words.slice(1) + ' — ' + host;
    }
    return host;
  } catch (e) {
    return raw;
  }
}

function fmtWhen(d) {
  return 'just now';
}

function render() {
  listEl.innerHTML = '';
  if (items.length === 0) {
    emptyEl.style.display = 'block';
    return;
  }
  emptyEl.style.display = 'none';
  items.forEach(it => {
    const li = document.createElement('li');
    li.className = 'item';
    li.innerHTML = `
      <a class="title" href="${it.url}" target="_blank" rel="noopener">${it.title}</a>
      <div class="url">${it.url}</div>
      <div class="meta">Saved ${it.when}</div>
    `;
    listEl.appendChild(li);
  });
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  let val = input.value.trim();
  if (!val) return;
  if (!/^https?:\/\//i.test(val)) val = 'https://' + val;
  items.unshift({ url: val, title: titleFromUrl(val), when: fmtWhen(new Date()) });
  input.value = '';
  input.focus();
  render();
});

