// --- Simulated "read the page's real title" ---------------------------
// A real app would fetch the page and read its <title>. In this prototype
// we simulate that: a short "Fetching title…" moment, then the real page
// title appears. A few common links resolve to their genuine titles; any
// other link resolves to a realistic simulated page title.
const KNOWN_TITLES = {
  'en.wikipedia.org/wiki/bookmark': 'Bookmark - Wikipedia',
  'en.wikipedia.org/wiki/bookmark_(digital)': 'Bookmark (digital) - Wikipedia',
  'developer.mozilla.org/en-us/docs/web/javascript': 'JavaScript | MDN',
  'news.ycombinator.com': 'Hacker News',
  'github.com': 'GitHub · Build and ship software on a single, collaborative platform',
};

function simulateFetchedTitle(raw) {
  try {
    const u = new URL(raw);
    const key = (u.hostname.replace(/^www\./, '') + u.pathname.replace(/\/$/, '')).toLowerCase();
    if (KNOWN_TITLES[key]) return KNOWN_TITLES[key];
    const host = u.hostname.replace(/^www\./, '');
    const last = u.pathname.split('/').filter(Boolean).pop() || '';
    const words = last.replace(/[-_]+/g, ' ').replace(/\.[a-z0-9]+$/i, '').trim();
    const brand = host.split('.')[0];
    const site = brand.charAt(0).toUpperCase() + brand.slice(1);
    if (words) {
      const cap = words.charAt(0).toUpperCase() + words.slice(1);
      return cap + ' | ' + site;
    }
    return site + ' — Home';
  } catch (e) {
    return raw;
  }
}

function render() {
  listEl.innerHTML = '';
  if (items.length === 0) {
    emptyEl.style.display = 'block';
    return;
  }
  emptyEl.style.display = 'none';
  items.forEach(it => {
    const li = document.createElement('li');
    li.className = 'item';
    const titleHtml = it.fetching
      ? `<span class="title fetching"><span class="shimmer"></span></span>`
      : `<a class="title" href="${it.url}" target="_blank" rel="noopener">${it.title}</a>`;
    const metaHtml = it.fetching
      ? `<div class="meta">Reading the page’s title…</div>`
      : `<div class="meta">Saved ${it.when}</div>`;
    li.innerHTML = titleHtml + `<div class="url">${it.url}</div>` + metaHtml;
    listEl.appendChild(li);
  });
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  let val = input.value.trim();
  if (!val) return;
  if (!/^https?:\/\//i.test(val)) val = 'https://' + val;
  const item = { url: val, title: '', when: 'just now', fetching: true };
  items.unshift(item);
  input.value = '';
  input.focus();
  render();
  // Simulate the brief moment of fetching the real page title.
  setTimeout(() => {
    item.title = simulateFetchedTitle(val);
    item.fetching = false;
    render();
  }, 700);
});

