input.new_string:
  emptyEl.style.display = 'none';
  items.forEach(it => {
    const li = document.createElement('li');
    li.className = 'item';
    if (it.editing) {
      li.innerHTML = `<div class="editrow"><input type="text" value="${it.title.replace(/"/g,'&quot;')}" /><button class="save">Save</button><button class="cancel">Cancel</button></div><div class="url">${it.url}</div>`;
      const inp = li.querySelector('input');
      const commit = () => { const v = inp.value.trim(); if (v) it.title = v; it.editing = false; render(); };
      li.querySelector('.save').onclick = commit;
      li.querySelector('.cancel').onclick = () => { it.editing = false; render(); };
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') commit(); if (e.key === 'Escape') { it.editing = false; render(); } });
      setTimeout(() => { inp.focus(); inp.select(); }, 0);
    } else if (it.fetching) {
      li.innerHTML = `<div class="titlerow"><span class="title fetching"><span class="shimmer"></span></span></div><div class="url">${it.url}</div><div class="meta">Reading the page’s title…</div>`;
    } else {
      li.innerHTML = `<div class="titlerow"><a class="title" href="${it.url}" target="_blank" rel="noopener">${it.title}</a><button class="pencil" title="Rename">✎</button></div><div class="url">${it.url}</div><div class="meta">Saved ${it.when}</div>`;
      li.querySelector('.pencil').onclick = () => { items.forEach(x => x.editing = false); it.editing = true; render(); };
    }
    listEl.appendChild(li);
  });
}

