if(it.editing){
  li.innerHTML=`<div class="editrow"><input type="text" value="${it.title.replace(/"/g,'&quot;')}" /><button class="save">Save</button><button class="cancel">Cancel</button></div><div class="url">${it.url}</div>`;
  const inp=li.querySelector('input');
  const commit=()=>{const v=inp.value.trim();if(v)it.title=v;it.editing=false;render();};
  li.querySelector('.save').onclick=commit;li.querySelector('.cancel').onclick=()=>{it.editing=false;render();};
  inp.addEventListener('keydown',e=>{if(e.key==='Enter')commit();if(e.key==='Escape'){it.editing=false;render();}});
  setTimeout(()=>{inp.focus();inp.select();},0);
}else if(it.fetching){

input.new_string:
if(it.editing){
  li.innerHTML=`<div class="editform">
    <div><label>Title</label><input class="ftitle" value="${esc(it.title)}" /></div>
    <div class="tagfield"><label>Tags (comma-separated)</label><input class="ftags" value="${esc(it.tags.join(', '))}" autocomplete="off" /><div class="suggest"></div></div>
    <div class="actions"><button class="save">Save</button><button class="cancel">Cancel</button></div>
  </div><div class="url" style="margin-top:8px">${it.url}</div>`;
  const ftitle=li.querySelector('.ftitle');const ftags=li.querySelector('.ftags');const sug=li.querySelector('.suggest');
  const commit=()=>{const t=ftitle.value.trim();if(t)it.title=t;it.tags=ftags.value.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);it.editing=false;render();};
  li.querySelector('.save').onclick=commit;
  li.querySelector('.cancel').onclick=()=>{it.editing=false;render();};
  ftitle.addEventListener('keydown',e=>{if(e.key==='Escape'){it.editing=false;render();}});
  function showSug(){
    const parts=ftags.value.split(',');const frag=parts[parts.length-1].trim().toLowerCase();
    const already=ftags.value.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);
    const c=allTags();let opts=Object.keys(c).filter(t=>t.includes(frag)&&!already.slice(0,-1).includes(t));
    if(frag==='')opts=Object.keys(c).filter(t=>!already.slice(0,-1).includes(t));
    opts=opts.sort((a,b)=>c[b]-c[a]).slice(0,6);
    if(!opts.length){sug.classList.remove('open');return;}
    sug.innerHTML=opts.map(t=>`<div class="opt" data-t="${t}">#${t}<span class="cnt">${c[t]} saved</span></div>`).join('');
    sug.querySelectorAll('.opt').forEach(o=>o.onclick=()=>{const p=ftags.value.split(',');p[p.length-1]=o.dataset.t;ftags.value=p.map(x=>x.trim()).filter(Boolean).join(', ')+', ';sug.classList.remove('open');ftags.focus();});
    sug.classList.add('open');
  }
  ftags.addEventListener('input',showSug);ftags.addEventListener('focus',showSug);
  ftags.addEventListener('blur',()=>setTimeout(()=>sug.classList.remove('open'),150));
  ftags.addEventListener('keydown',e=>{if(e.key==='Escape'){it.editing=false;render();}});
  setTimeout(()=>{ftitle.focus();ftitle.select();},0);
}else if(it.fetching){

